import sys
from heapq import heappush, heappop

def ii(): return int(sys.stdin.readline().rstrip())
def gl(): return list(map(int, sys.stdin.readline().split()))
def glm(h, w):
    a = []
    for i in range(h):
        a.append(gl())
    return a

def main():
    n = ii()
    a = glm(n-1, 3)
    h = []
    heappush(h, (0, 0))
    min_time = [float('inf')] * n
    min_time[0] = 0

    while h:
        now, st = heappop(h)

        if st == n-1:
            print(now)
            return

        if st + 1 < n and now + a[st][0] < min_time[st + 1]:
            min_time[st + 1] = now + a[st][0]
            heappush(h, (min_time[st + 1], st + 1))

        jump_to = a[st][2] - 1
        if jump_to < n and now + a[st][1] < min_time[jump_to]:
            min_time[jump_to] = now + a[st][1]
            heappush(h, (min_time[jump_to], jump_to))

if __name__ == "__main__":
    main()
